-- Remove the old fixture's requesting-clinic defaults; runtime policy resolves clinical destinations.
update RHN_BD_ORG_CATALOG_ITEM set ID_DEPT_DEFAULT=null,REVISION=REVISION+1,DT_UPDATED=current_timestamp
where ID_TNT=362387869790209 and ID_ORG=362387869790211 and ID_DEPT_DEFAULT=362387869790212 and REVISION=0
and ID_CATALOG_ITEM in (select ID_CATALOG_ITEM from RHN_BD_SVC_ITEM where SD_SVC_TYPE in ('LABORATORY','EXAMINATION'));
